/**
     * Runs the given recipe over the input buffer and returns the output.
     *
     * @param {Object[]} recipeConfig
     * @param {ArrayBuffer} [input=this.inputBuffer]
     * @returns {ArrayBuffer}
     */
async _runRecipe(recipeConfig, input=this.inputBuffer) {
        input = input instanceof ArrayBuffer ? input : input.buffer;
        const dish = new Dish();
        dish.set(input, Dish.ARRAY_BUFFER);

        if (isWorkerEnvironment()) self.loadRequiredModules(recipeConfig);

        const recipe = new Recipe(recipeConfig);
        try {
            await recipe.execute(dish);
            // Return an empty buffer if the recipe did not run to completion
            if (recipe.lastRunOp === recipe.opList[recipe.opList.length - 1]) {
                return await dish.get(Dish.ARRAY_BUFFER);
            } else {
                return new ArrayBuffer();
            }
        } catch (err) {
            // If there are errors, return an empty buffer
            return new ArrayBuffer();
        }
    }

/**
     * @param {Object} state - The current state of the recipe.
     * @param {number} state.progress - The current position in the recipe.
     * @param {Dish} state.dish - The Dish being operated on.
     * @param {Operation[]} state.opList - The list of operations in the recipe.
     * @returns {Object} The updated state of the recipe.
     */
async run(state) {
        const opList     = state.opList,
            inputType    = opList[state.progress].inputType,
            outputType   = opList[state.progress].outputType,
            input        = await state.dish.get(inputType),
            ings         = opList[state.progress].ingValues,
            [splitDelim, mergeDelim, ignoreErrors] = ings,
            subOpList    = [];
        let inputs       = [],
            i;

        if (input)
            inputs = input.split(splitDelim);

        // Set to 1 as if we are here, then there is one, the current one.
        let numOp = 1;
        // Create subOpList for each tranche to operate on
        // all remaining operations unless we encounter a Merge
        for (i = state.progress + 1; i < opList.length; i++) {
            if (opList[i].name === "Merge" && !opList[i].disabled) {
                numOp--;
                if (numOp === 0 || opList[i].ingValues[0])
                    break;
                else
                    // Not this Fork's Merge.
                    subOpList.push(opList[i]);
            } else {
                if (opList[i].name === "Fork" || opList[i].name === "Subsection")
                    numOp++;
                subOpList.push(opList[i]);
            }
        }

        const recipe = new Recipe();
        const outputs = [];
        let progress = 0;

        state.forkOffset += state.progress + 1;

        recipe.addOperations(subOpList);

        // Take a deep(ish) copy of the ingredient values
        const ingValues = subOpList.map(op => JSON.parse(JSON.stringify(op.ingValues)));

        // Run recipe over each tranche
        for (i = 0; i < inputs.length; i++) {
            // Baseline ing values for each tranche so that registers are reset
            recipe.opList.forEach((op, i) => {
                op.ingValues = JSON.parse(JSON.stringify(ingValues[i]));
            });

            const dish = new Dish();
            dish.set(inputs[i], inputType);

            try {
                progress = await recipe.execute(dish, 0, state);
            } catch (err) {
                if (!ignoreErrors) {
                    throw err;
                }
                progress = err.progress + 1;
            }
            outputs.push(await dish.get(outputType));
        }

        state.dish.set(outputs.join(mergeDelim), outputType);
        state.progress += progress;
        return state;
    }

