            const cRotor = this.baseRotors[0].copy();
            const end1 = a2i(edge.node1.letter);
            const end2 = a2i(edge.node2.letter);
            const scrambler = new Scrambler(this.sharedScrambler, cRotor, edge.pos, end1, end2);
